insert into public.trainings (key, title, kind, category, path_group, description, resource_url, ext_id, minutes, source, sort, active, body, updated_at) values ('slack:general:28', 'Setting up a new person: accounts, channels, website and drives', 'read', 'People and HR', 'People and HR', '1. Adding a google account (see here for instructions: https://support.google.com/a/answer/33310?hl=en)
- Make sure to make their email in this easy format: firstname.lastname@welfareavenue.com
- Also to set a temporary password and tick "Ask for a new password when they sign in", then share it with them one to one
- They must open a separate Google Chrome window from their personal one to add their account and have their workspace separate from their school or personal space
2. Add Slack account using their WA email you just created
3. Add them to all necessary Slack channels: #general, #training
4. Add member on to the website (see attached video)
- Make sure they sign up first on the website, with their WA email (not with Google manually) and they add a photo. Then watch the attached video to see how to add them.
- You can consider this training done as well "Adding member to Website"
5. Add member to necessary shared drives + necessary email groups
6. Get photo from member for Newsletter announcement', null, null, 20, 'slack', 150, true, '{"from": "Slack training list: General Trainings", "rows": [28]}'::jsonb, now())
on conflict (key) where key is not null do update set title = excluded.title, kind = excluded.kind, category = excluded.category, path_group = excluded.path_group, description = excluded.description, resource_url = excluded.resource_url, ext_id = excluded.ext_id, minutes = excluded.minutes, body = excluded.body, updated_at = now();

update public.trainings set description = case when coalesce(description, '') like '%Extra, if you want to go further:
- [CRA%' then description else trim(both E'\n' from coalesce(description, '') || E'\n\n' || 'Extra, if you want to go further:
- [CRA: sample official donation receipts](https://www.canada.ca/en/revenue-agency/services/charities-giving/charities/sample-official-donation-receipts.html)
- [A video walkthrough of receipting](https://www.youtube.com/watch?v=R5curWncFnQ)
- [The Canadian charitable receipt expert (a custom GPT)](https://chatgpt.com/g/g-673812032f98819185891d4a9cdfe417-canadian-charitable-receipt-expert)') end, updated_at = now() where id = 8;

