insert into public.trainings (key, title, kind, category, path_group, description, resource_url, ext_id, minutes, source, sort, active, body, updated_at) values ('slack:outreach:49', 'Running a tabling event', 'read', 'Fundraising', 'Student clubs and tabling', 'Tabling Must Haves:

- A computer to display videos and QR code
- QR CODE: https://www.canva.com/design/DAF_b_87rXE/cTsk8udrOWIms-quYE_LQw/edit?utm_content=DA[…]m_campaign=designshare&utm_medium=link2&utm_source=sharebutton
- WA Pennies & Table Cloth
- Posters (get either from storage unit in Park ex or print them out from here https://drive.google.com/drive/folders/1o9OB9j-BOekg0PyQ8DQ2XQPi5WX7QY9G?usp=sharing)

1. Make a request for table (see training for tabling request)
2. Announce to team about upcoming tabling event in general chat. Proceed to individual DMs
3.  Ensure you (or someone attending will be attending the tabling brings the following:
- QR CODEs to scan
- https://forms.gle/w2Cr5HBhBXyKUReYA (for recruitment)
- Pennies
- Posters
- If fundraising ensure Square Payment is there

All items are in the storage unit and payment machine is with Steel

4. Make group chat of details and time of each member (minimum 2 members must be attending).

More to watch or read:

- https://forms.gle/w2Cr5HBhBXyKUReYA', null, null, 15, 'slack', 100, true, '{"from": "Slack training list: Outreach Trainings", "rows": [34, 49]}'::jsonb, now())
