insert into public.trainings (key, title, kind, category, path_group, description, resource_url, ext_id, minutes, source, sort, active, body, updated_at) values ('slack:marketing:22', 'Keela forms: the full guide', 'read', 'Keela (donor CRM)', 'Keela donor CRM', 'Read all training articles and watch all videos:

- [1. How to Create a Form](https://support.keela.co/hc/en-us/articles/360043185292-1-How-to-Create-a-Form)
- [2. The Forms Overview Tab](https://support.keela.co/hc/en-us/articles/360043186192-2-The-Forms-Overview-Tab)
- [3. The Setup Tab](https://support.keela.co/hc/en-us/articles/360038233272-3-The-Setup-Tab)
- [4. Adding Fields or Questions to your Form](https://support.keela.co/hc/en-us/articles/360043188432-4-Adding-Fields-or-Questions-to-your-Form)
- [5. Customize the Contents Sections of your Form Page](https://support.keela.co/hc/en-us/articles/360043667591-5-Customize-the-Contents-Sections-of-your-Form-Page)
- [6. Customize the Contents Sections of your Thank You Page](https://support.keela.co/hc/en-us/articles/360043230752-6-Customize-the-Contents-Sections-of-your-Thank-You-Page)
- [7. Customize the Contents Sections of your Form Closed Page](https://support.keela.co/hc/en-us/articles/360043668431-7-Customize-the-Contents-Sections-of-your-Form-Closed-Page)
- [8. Customizing the Style Settings of your entire Form](https://support.keela.co/hc/en-us/articles/360043669011-8-Customizing-the-Style-Settings-of-your-entire-Form)
- [9. The Settings Tab](https://support.keela.co/hc/en-us/articles/360043232592-9-The-Settings-Tab)
- [10. Sharing Your Forms](https://support.keela.co/hc/en-us/articles/360039258031-10-Sharing-Your-Forms)
- [11. View Your Form Responses](https://support.keela.co/hc/en-us/articles/360039258811-11-View-Your-Form-Responses)
- [12. View the Fundraising Tab](https://support.keela.co/hc/en-us/articles/360039814691-12-View-the-Fundraising-Tab)
- [Exporting Your Form Responses](https://support.keela.co/hc/en-us/articles/360054112111-Exporting-Your-Form-Responses)', null, null, 45, 'slack', 150, true, '{"from": "Slack training list: Marketing Department Trainings", "rows": [22]}'::jsonb, now())
