insert into public.trainings (key, title, kind, category, path_group, description, source, sort, minutes, xp, active, body, updated_at) values ('lesson:leading-a-team', 'Running a team: meetings, follow-up and new people', 'lesson', 'Leadership', 'Leading a team', 'How Welfare Avenue leads run a team: meetings people want to come to, work that keeps moving between them, and new people brought in properly. Written from the leads’ own guidance in Slack.', 'hub', 10, 12, 60, true, '{"v": 1, "cover": "purple", "summary": "How Welfare Avenue leads run a team: meetings people want to come to, work that keeps moving between them, and new people brought in properly. Written from the leads’ own guidance in Slack.", "chapters": [{"id": "before", "t": "Before the meeting", "blocks": [{"type": "lead", "text": "A good meeting is mostly made before it starts. Give yourself an hour to prepare, ideally the morning of the meeting."}, {"type": "cards", "items": [{"t": "Confirm attendance", "d": "Message the team 24 hours before to confirm who is coming.", "icon": "chat"}, {"t": "Fix the time early", "d": "If attendance drops or the time stops working, run a When2Meet. Plan one ahead of exams, new members and the September, January and May schedule changes.", "icon": "clock"}, {"t": "Build the agenda from the work", "d": "Open your team’s tasks in the Hub before you write the agenda. Ask members to add their own agenda items: it saves you time and they own them.", "icon": "list"}, {"t": "Check the workload", "d": "Someone with under four hours of work a week needs something that fits their role, or a teammate to help.", "icon": "people"}]}, {"type": "quote", "text": "Prep at least 1 hour before meeting, ideally the morning of the day of the meeting.", "by": "Running WA Meetings: Tips & Guidelines"}]}, {"id": "during", "t": "In the meeting", "blocks": [{"type": "lead", "text": "People stay engaged when they have a part to play."}, {"type": "cards", "items": [{"t": "Open with an icebreaker", "d": "A quick peak and pit of the week, especially with a new team or a short meeting.", "icon": "spark"}, {"t": "Name a note-taker", "d": "Every meeting has someone writing the notes and the tasks. It is not optional.", "icon": "edit"}, {"t": "Members present their work", "d": "Each person shows what they did. Ask for opinions on what you pitch.", "icon": "mic"}, {"t": "Leave with tasks", "d": "Set the tasks in the meeting, with owners, and follow up on them at the next one. Upload the transcript and the Hub creates them for you.", "icon": "check"}]}]}, {"id": "between", "t": "Between meetings", "blocks": [{"type": "lead", "text": "Work keeps moving when the conversation does."}, {"type": "cards", "items": [{"t": "Check in on tasks", "d": "If you see no progress or check-ins during the week, ask. An @mention in the Hub sends the person a Slack message.", "icon": "bolt"}, {"t": "Keep leaders in the loop", "d": "Talk in the open team channels so the leaders above you can support and back you up.", "icon": "people"}, {"t": "Late or absent?", "d": "People tell you 24 hours ahead (one hour in an emergency). Talk to anyone who does not.", "icon": "clock"}, {"t": "Plan around busy weeks", "d": "When you know people will be busy, delegate early.", "icon": "target"}]}, {"type": "quote", "text": "Dont be too lenient it’ll backfire in long run", "by": "Team Meetings & Leadership Guidance"}]}, {"id": "people", "t": "New people and growing your team", "blocks": [{"type": "lead", "text": "New members decide in their first weeks whether they stay."}, {"type": "cards", "items": [{"t": "Touch base every meeting", "d": "Check in with each new person and let them go faster than week by week if they want to.", "icon": "user"}, {"t": "Stay after the call", "d": "Keep a new person back for a few minutes to connect and train them where needed.", "icon": "chat"}, {"t": "Assign trainings", "d": "Give a new team as many Academy trainings as fit, during quiet weeks, and make new ones when something is missing.", "icon": "book"}, {"t": "Set them up properly", "d": "Make sure everyone is signed in to Slack with notifications on and to their Welfare Avenue Google account, and invite them to other teams’ meetings to see how they work.", "icon": "home"}]}, {"type": "callout", "tone": "info", "t": "Done when", "text": "you have run a meeting with a confirmed time, an agenda built from the team’s tasks, a named note-taker, and tasks set with owners."}]}], "quiz": {"pass": 0.75, "questions": [{"q": "When should you confirm who is coming to your team meeting?", "a": ["The morning of the meeting", "24 hours before", "At the start of the meeting"], "c": 1, "why": "A message 24 hours ahead gives you time to fix the time or the agenda."}, {"q": "Someone on your team has under four hours of work a week. What do you do?", "a": ["Leave it: they are a volunteer", "Find something that fits their role, or pair them with a teammate", "Remove them from the team"], "c": 1, "why": "Under-used people drift away; the right piece of work keeps them in."}, {"q": "Who takes the notes and writes the tasks?", "a": ["Whoever remembers", "Someone named at every meeting", "Nobody: the leader remembers"], "c": 1, "why": "Naming a note-taker every time is the one non-negotiable in our guidance."}, {"q": "A new member joined two weeks ago. What helps most?", "a": ["Waiting for them to ask", "Checking in every meeting and staying after the call to train them", "Giving them the hardest task"], "c": 1, "why": "Early attention and training is what keeps new people."}]}}'::jsonb, now())
on conflict (key) where key is not null do update set title = excluded.title, path_group = excluded.path_group, description = excluded.description, body = excluded.body, minutes = excluded.minutes, updated_at = now();

